import { writeFileSync } from 'node:fs';
import { contrast } from '../src/contrast.ts';
import { SCHEMES, TEXT_PAIRS, UI_PAIRS, type ColourName, type SchemeName } from '../src/tokens.ts';

// Writes docs/design/contrast.md from the tokens. Usage: npm run contrast -w @repr-werkbank/web
const out = new URL('../../../docs/design/contrast.md', import.meta.url);

const lines = [
  '# Contrast ratios of the design tokens',
  '',
  'Generated by `npm run contrast -w @repr-werkbank/web` from `packages/web/src/tokens.ts`; do not edit by hand.',
  'Ratio = (L1 + 0.05) / (L2 + 0.05) with the WCAG 2.x relative luminance of sRGB (`packages/web/src/contrast.ts`).',
  '`test/contrast.test.ts` fails when a text pair is below 4.5 (WCAG 1.4.3, AA) or a border/focus/symbol pair is below 3 (WCAG 1.4.11, AA).',
  'The hairline colour `line` separates zones and is decorative; it is exempt.',
  '',
];

for (const [title, pairs, min] of [
  ['Text on surface', TEXT_PAIRS, 4.5],
  ['Borders, focus ring and symbols on surface', UI_PAIRS, 3],
] as const) {
  lines.push(`## ${title} (minimum ${min})`, '', '| Foreground | Surface | Light | Dark |', '| --- | --- | ---: | ---: |');
  for (const [fg, surfaces] of Object.entries(pairs)) {
    for (const bg of surfaces) {
      const cell = (s: SchemeName): string => {
        const p = SCHEMES[s];
        const r = contrast(p[fg as ColourName], p[bg]);
        return `${r.toFixed(2)}${r >= min ? '' : ' FAIL'}`;
      };
      lines.push(`| ${fg} | ${bg} | ${cell('light')} | ${cell('dark')} |`);
    }
  }
  lines.push('');
}

writeFileSync(out, lines.join('\n'));
console.log(`wrote ${out.pathname}`);
